 * const?: string|int|bool|null, pattern?: string, minimum?: int, maximum?: int, items?: Rule}
 */
final class CheckSchema
{
    /** @return EnvelopeObject */
    public static function document(string $json, string $message = ''): object
    {
        return self::validated(json_decode($json, associative: false, depth: 64, flags: JSON_THROW_ON_ERROR), $message);
    }

    /** @return EnvelopeObject */
    private static function validated(mixed $value, string $message): object
    {
        self::assertValid($value, $message);
        return $value;
    }

    /** @phpstan-assert EnvelopeObject $value */
    public static function assertValid(mixed $value, string $message = ''): void
    {
        \Testo\Assert::true(self::valid($value), $message);
    }

    /** @phpstan-assert-if-true EnvelopeObject $value */
    public static function valid(mixed $value): bool
    {
        // The checked-in schema uses exactly the finite keyword/value grammar declared above.
        /** @var Rule $schema */
        $schema = json_decode(\Tablo\RequiredFile::bytes(file_get_contents(dirname(__DIR__, levels: 2) . '/contracts/check-output-v1.schema.json')), associative: true, depth: 64, flags: JSON_THROW_ON_ERROR);
        return self::matches($value, $schema, $schema);
    }

    /**
     * @param Rule $rule
     * @param Rule $root
     */
    public static function matches(mixed $value, array $rule, array $root): bool
    {

        $supported = ['$schema', 'title', '$defs', '$ref', 'type', 'required', 'additionalProperties', 'properties',
            'anyOf', 'allOf', 'if', 'then', 'else', 'enum', 'const', 'pattern', 'minimum', 'maximum', 'items'];
        if (array_diff(array_keys($rule), $supported) !== []) { throw new \LogicException('Unsupported schema assertion.'); }
        if (!SchemaLogic::matches($value, $rule, $root)) { return false; }
        if (!SchemaScalar::matches($value, $rule, $root)) { return false; }
        if (!SchemaObject::matches($value, $rule, $root)) { return false; }
        if (!SchemaItems::matches($value, $rule, $root)) { return false; }
        return SchemaBounds::matches($value, $rule);
    }
}
